create FUNCTION [dbo].[fn_get_mstoptvalue] 
( 
   @p_master_id varchar(max) = '-',
   @p_plan_id varchar(max) = '-',
   @p_category_id varchar(max) = '-',
   @p_option_id varchar(max) = '-'
)
RETURNS varchar(max)
AS 
   /*Generated by SQL Server Migration Assistant for Oracle version 6.0.0.*/
   BEGIN

      DECLARE
         @v_option_value varchar(150)

      SELECT @v_option_value = A.OPTION_VALUE
      FROM dbo.TH_MST_OPTION A
      WHERE 
         A.MASTER_ID = @p_master_id AND 
         A.PLAN_ID = @p_plan_id AND 
         A.CATEGORY_ID = @p_category_id AND 
         A.OPTION_ID = @p_option_id

      RETURN @v_option_value

   END
